  8	import br.com.marealta.database.Database;
  9	import br.com.marealta.pricing.PricingService;
 10	import br.com.marealta.report.OccupancyReport;
 11	import br.com.marealta.report.RatePlansReport;
 12	import br.com.marealta.report.RevenueReport;
 13	import br.com.marealta.report.TourismTaxReport;
 14	import br.com.marealta.repository.MessageRepository;
 15	import br.com.marealta.repository.ReservationRepository;
 16	import br.com.marealta.repository.RoomRepository;
 17	import br.com.marealta.service.DocumentService;
 18	import br.com.marealta.service.MessageService;
 19	import br.com.marealta.service.ReservationService;
 20	import com.fasterxml.jackson.databind.ObjectMapper;
 21	import com.fasterxml.jackson.databind.SerializationFeature;
 22	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 23	import io.javalin.Javalin;
 24	import io.javalin.http.BadRequestResponse;
 25	import io.javalin.http.ConflictResponse;
 26	import io.javalin.http.NotFoundResponse;
 27	import io.javalin.http.UnprocessableContentResponse;
 28	import io.javalin.json.JavalinJackson;
 29	
 30	public class App {
 31	    public static void main(String[] args) {
 32	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 33	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 34	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 35	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 36	
 37	        Database database = new Database(dbUrl, dbUser, dbPassword);
 38	        database.initialize();
 39	
 40	        RoomRepository roomRepository = new RoomRepository(database);
 41	        ReservationRepository reservationRepository = new ReservationRepository(database);
 42	        MessageRepository messageRepository = new MessageRepository(database);
 43	
 44	        PricingService pricingService = new PricingService();
 45	        MessageService messageService = new MessageService(messageRepository);
 46	        ReservationService reservationService = new ReservationService(
 47	            reservationRepository, roomRepository, pricingService, messageService
 48	        );
 49	        DocumentService documentService = new DocumentService();
 50	
 51	        RoomController roomController = new RoomController(roomRepository);
 52	        ReservationController reservationController = new ReservationController(
 53	            reservationService, documentService, roomRepository
 54	        );
 55	        MessageController messageController = new MessageController(messageService);
 56	
 57	        OccupancyReport occupancyReport = new OccupancyReport(reservationRepository);
 58	        RevenueReport revenueReport = new RevenueReport(reservationRepository);
 59	        TourismTaxReport tourismTaxReport = new TourismTaxReport(reservationRepository);
 60	        RatePlansReport ratePlansReport = new RatePlansReport(reservationRepository);
 61	        ReportController reportController = new ReportController(
 62	            occupancyReport, revenueReport, tourismTaxReport, ratePlansReport
 63	        );
 64	
 65	        ObjectMapper objectMapper = new ObjectMapper()
 66	            .registerModule(new JavaTimeModule())
 67	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 68	
 69	        Javalin app = Javalin.create(config -> {
 70	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 71	        });
 72	
 73	        app.get("/rooms", roomController::listRooms);
 74	
 75	        app.post("/reservations", reservationController::createReservation);
 76	        app.get("/reservations/{id}", reservationController::getReservation);
 77	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 78	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 79	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 80	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 81	        app.get("/reservations/{id}/document", reservationController::getDocument);
 82	
 83	        app.get("/messages", messageController::listMessages);
 84	
 85	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 86	        app.get("/reports/revenue", reportController::getRevenueReport);
 87	        app.get("/reports/tourism-tax", reportController::getTourismTaxReport);
 88	        app.get("/reports/rate-plans", reportController::getRatePlansReport);
 89	
 90	        app.exception(ReservationService.RoomNotFoundException.class, (e, ctx) -> {
 91	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
 92	        });
 93	
 94	        app.exception(ReservationService.ReservationNotFoundException.class, (e, ctx) -> {
 95	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
 96	        });
 97	
 98	        app.exception(ReservationService.RoomUnavailableException.class, (e, ctx) -> {
 99	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
100	        });
101	
102	        app.exception(ReservationService.OperationNotAllowedException.class, (e, ctx) -> {
103	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
104	        });
105	
106	        app.exception(ReservationService.CapacityExceededException.class, (e, ctx) -> {
107	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
108	        });
109	
110	        app.exception(ReservationService.InvalidRequestException.class, (e, ctx) -> {
111	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request parameters"));
112	        });
113	
114	        app.exception(BadRequestResponse.class, (e, ctx) -> {
115	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
116	        });
117	
118	        app.exception(NumberFormatException.class, (e, ctx) -> {
119	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid ID format"));
120	        });
121	
122	        app.exception(Exception.class, (e, ctx) -> {
123	            e.printStackTrace();
124	            if (!ctx.res().isCommitted()) {
125	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
126	            }
127	        });
128	
129	        app.start(port);
130	
131	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
132	        System.out.println("Servidor rodando na porta " + port);
133	    }
134	}
