207	package br.com.marealta.api.controller;
208	
209	import br.com.marealta.api.dto.CreateReservationRequest;
210	import br.com.marealta.api.dto.DocumentResponse;
211	import br.com.marealta.api.dto.ReservationResponse;
212	import br.com.marealta.domain.Reservation;
213	import br.com.marealta.domain.ReservationStatus;
214	import br.com.marealta.domain.RoomType;
215	import br.com.marealta.repository.RoomRepository;
216	import br.com.marealta.service.DocumentService;
217	import br.com.marealta.service.ReservationService;
218	import io.javalin.http.Context;
219	
220	public class ReservationController {
221	    private final ReservationService reservationService;
222	    private final DocumentService documentService;
223	    private final RoomRepository roomRepository;
224	
225	    public ReservationController(
226	            ReservationService reservationService,
227	            DocumentService documentService,
228	            RoomRepository roomRepository) {
229	        this.reservationService = reservationService;
230	        this.documentService = documentService;
231	        this.roomRepository = roomRepository;
232	    }
233	
234	    public void createReservation(Context ctx) {
235	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
236	
237	        Reservation reservation = new Reservation();
238	        reservation.setRoomNumber(request.roomNumber());
239	        reservation.setGuestName(request.guestName());
240	        reservation.setGuestEmail(request.guestEmail());
241	        reservation.setGuestCpf(request.guestCpf());
242	        reservation.setCheckIn(request.checkIn());
243	        reservation.setCheckOut(request.checkOut());
244	        reservation.setGuests(request.guests());
245	        reservation.setRatePlan(request.ratePlan());
246	
247	        Reservation created = reservationService.createReservation(reservation);
248	
249	        ctx.status(201).json(ReservationResponse.from(created));
250	    }
251	
252	    public void getReservation(Context ctx) {
253	        Long id = Long.parseLong(ctx.pathParam("id"));
254	        Reservation reservation = reservationService.findReservationById(id);
255	        ctx.json(ReservationResponse.from(reservation));
256	    }
257	
258	    public void confirmReservation(Context ctx) {
259	        Long id = Long.parseLong(ctx.pathParam("id"));
260	        Reservation reservation = reservationService.confirmReservation(id);
261	        ctx.json(ReservationResponse.from(reservation));
262	    }
263	
264	    public void cancelReservation(Context ctx) {
265	        Long id = Long.parseLong(ctx.pathParam("id"));
266	        Reservation reservation = reservationService.cancelReservation(id);
267	        ctx.json(ReservationResponse.from(reservation));
268	    }
269	
270	    public void checkIn(Context ctx) {
271	        Long id = Long.parseLong(ctx.pathParam("id"));
272	        Reservation reservation = reservationService.checkIn(id);
273	        ctx.json(ReservationResponse.from(reservation));
274	    }
275	
276	    public void checkOut(Context ctx) {
277	        Long id = Long.parseLong(ctx.pathParam("id"));
278	        Reservation reservation = reservationService.checkOut(id);
279	        DocumentResponse document = buildDocument(reservation);
280	        ctx.json(document);
281	    }
282	
283	    public void getDocument(Context ctx) {
284	        Long id = Long.parseLong(ctx.pathParam("id"));
285	        Reservation reservation = reservationService.findReservationById(id);
286	
287	        if (reservation.getStatus() == ReservationStatus.PENDING) {
288	            throw new IllegalStateException("Document not available for pending reservation");
289	        }
290	
291	        DocumentResponse document = buildDocument(reservation);
292	        ctx.json(document);
293	    }
294	
295	    private DocumentResponse buildDocument(Reservation reservation) {
296	        RoomType roomType = roomRepository.findByNumber(reservation.getRoomNumber())
297	            .map(room -> room.getType())
298	            .orElse(null);
299	
300	        return new DocumentResponse(
301	            "Comprovante de reserva",
302	            reservation.getId(),
303	            reservation.getGuestName(),
304	            reservation.getGuestCpf(),
305	            reservation.getRoomNumber(),
306	            roomType,
307	            reservation.getCheckIn(),
308	            reservation.getCheckOut(),
309	            reservation.getNights(),
310	            reservation.getSubtotal(),
311	            reservation.getDiscount(),
312	            reservation.getTotal()
313	        );
314	    }
315	}
