 11	public class DocumentService {
 12	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 13	
 14	    public String generateReceiptText(Reservation reservation) {
 15	        StringBuilder receipt = new StringBuilder();
 16	
 17	        receipt.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
 18	        receipt.append(String.format("Hóspede: %s (CPF %s)%n",
 19	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
 20	
 21	        String roomType = getRoomType(reservation.getRoomNumber());
 22	        receipt.append(String.format("Quarto: %s (%s)%n",
 23	            reservation.getRoomNumber(), roomType));
 24	
 25	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s%n",
 26	            reservation.getCheckIn().format(DATE_FORMATTER),
 27	            reservation.getCheckOut().format(DATE_FORMATTER),
 28	            reservation.getNights(),
 29	            reservation.getNights() == 1 ? "diária" : "diárias"));
 30	
 31	        receipt.append(String.format("Diárias: %s%n", formatMoney(reservation.getSubtotal())));
 32	
 33	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 34	            receipt.append(String.format("Desconto: %s%n", formatMoney(reservation.getDiscount())));
 35	        }
 36	
 37	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
 38	
 39	        return receipt.toString();
 40	    }
 41	
 42	    private String getRoomType(String roomNumber) {
 43	        return switch (roomNumber) {
 44	            case "101", "102" -> "STANDARD";
 45	            case "201", "202" -> "DELUXE";
 46	            case "301" -> "SUITE";
 47	            default -> "";
 48	        };
 49	    }
 50	
 51	    private String formatCpf(String cpf) {
 52	        if (cpf.length() == 11) {
 53	            return String.format("%s.%s.%s-%s",
 54	                cpf.substring(0, 3),
 55	                cpf.substring(3, 6),
 56	                cpf.substring(6, 9),
 57	                cpf.substring(9, 11));
 58	        }
 59	        return cpf;
 60	    }
 61	
 62	    private String formatMoney(BigDecimal value) {
 63	        return String.format("R$ %,.2f", value).replace(",", ".");
 64	    }
 65	}
