124	
125	public class ReservationService {
126	    private final ReservationRepository reservationRepository;
127	    private final RoomRepository roomRepository;
128	    private final PricingService pricingService;
129	    private final MessageService messageService;
130	
131	    public ReservationService(
132	            ReservationRepository reservationRepository,
133	            RoomRepository roomRepository,
134	            PricingService pricingService,
135	            MessageService messageService) {
136	        this.reservationRepository = reservationRepository;
137	        this.roomRepository = roomRepository;
138	        this.pricingService = pricingService;
139	        this.messageService = messageService;
140	    }
141	
142	    public Reservation createReservation(Reservation reservation) {
143	        validateReservation(reservation);
144	
145	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
146	            .orElseThrow(() -> new RoomNotFoundException());
147	
148	        if (reservation.getGuests() > room.getCapacity()) {
149	            throw new CapacityExceededException();
150	        }
151	
152	        List<Reservation> conflicts = reservationRepository.findConflicting(
153	            reservation.getRoomNumber(),
154	            reservation.getCheckIn(),
155	            reservation.getCheckOut()
156	        );
157	
158	        if (!conflicts.isEmpty()) {
159	            throw new RoomUnavailableException();
160	        }
161	
162	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
163	        reservation.setNights(nights);
164	
165	        BigDecimal subtotal = pricingService.calculateSubtotal(room, reservation.getCheckIn(), reservation.getCheckOut());
166	        reservation.setSubtotal(subtotal);
167	
168	        BigDecimal discount = pricingService.calculateDiscount(subtotal, reservation.getRatePlan());
169	        reservation.setDiscount(discount);
170	
171	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
172	        reservation.setTotal(total);
173	
174	        return reservationRepository.save(reservation);
175	    }
176	
177	    public Reservation confirmReservation(Long id) {
178	        Reservation reservation = findReservationById(id);
179	
180	        if (reservation.getStatus() != ReservationStatus.PENDING) {
181	            throw new OperationNotAllowedException();
182	        }
183	
184	        reservation.setStatus(ReservationStatus.CONFIRMED);
185	        reservation.setAmountPaid(reservation.getTotal());
186	        reservationRepository.update(reservation);
187	
188	        messageService.sendConfirmationEmail(reservation);
189	
190	        return reservation;
191	    }
192	
193	    public Reservation cancelReservation(Long id) {
194	        Reservation reservation = findReservationById(id);
195	
196	        if (reservation.getStatus() != ReservationStatus.PENDING &&
197	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
198	            throw new OperationNotAllowedException();
199	        }
200	
201	        reservation.setStatus(ReservationStatus.CANCELLED);
202	
203	        BigDecimal refundAmount = switch (reservation.getRatePlan()) {
204	            case STANDARD -> reservation.getAmountPaid();
205	            case NON_REFUNDABLE -> BigDecimal.ZERO;
206	        };
207	
208	        reservation.setRefund(refundAmount);
209	        reservationRepository.update(reservation);
210	
211	        return reservation;
212	    }
213	
214	    public Reservation checkIn(Long id) {
215	        Reservation reservation = findReservationById(id);
216	
217	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
218	            throw new OperationNotAllowedException();
219	        }
220	
221	        reservation.setStatus(ReservationStatus.CHECKED_IN);
222	        reservationRepository.update(reservation);
223	
224	        return reservation;
225	    }
226	
227	    public Reservation checkOut(Long id) {
228	        Reservation reservation = findReservationById(id);
229	
230	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
231	            throw new OperationNotAllowedException();
232	        }
233	
234	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
235	        reservationRepository.update(reservation);
236	
237	        return reservation;
238	    }
239	
240	    public Reservation findReservationById(Long id) {
241	        return reservationRepository.findById(id)
242	            .orElseThrow(() -> new ReservationNotFoundException());
243	    }
244	
245	    private void validateReservation(Reservation reservation) {
246	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
247	            reservation.getCheckOut().isEqual(reservation.getCheckIn())) {
248	            throw new InvalidRequestException();
249	        }
250	
251	        if (reservation.getGuests() < 1) {
252	            throw new InvalidRequestException();
253	        }
254	    }
255	
256	    public static class RoomNotFoundException extends RuntimeException {}
257	    public static class ReservationNotFoundException extends RuntimeException {}
258	    public static class RoomUnavailableException extends RuntimeException {}
259	    public static class OperationNotAllowedException extends RuntimeException {}
260	    public static class CapacityExceededException extends RuntimeException {}
261	    public static class InvalidRequestException extends RuntimeException {}
262	}
263	package br.com.marealta.pricing;
264	
265	import br.com.marealta.domain.RatePlan;
266	import br.com.marealta.domain.Room;
267	
268	import java.math.BigDecimal;
269	import java.math.RoundingMode;
270	import java.time.LocalDate;
271	
272	public class PricingService {
273	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
274	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
275	
276	    public BigDecimal calculateNightPrice(Room room, LocalDate night) {
277	        BigDecimal basePrice = room.getNightlyRate();
278	        if (SeasonCalculator.isHighSeason(night)) {
279	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
280	        }
281	        return round(basePrice);
282	    }
283	
284	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
285	        BigDecimal subtotal = BigDecimal.ZERO;
286	        LocalDate current = checkIn;
287	
288	        while (current.isBefore(checkOut)) {
289	            BigDecimal nightPrice = calculateNightPrice(room, current);
290	            subtotal = subtotal.add(nightPrice);
291	            current = current.plusDays(1);
292	        }
293	
294	        return round(subtotal);
295	    }
296	
297	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
298	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
299	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
300	        }
301	        return BigDecimal.ZERO;
302	    }
303	
304	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
305	        return round(subtotal.subtract(discount));
306	    }
307	
308	    private BigDecimal round(BigDecimal value) {
309	        return value.setScale(2, RoundingMode.HALF_EVEN);
310	    }
311	}
312	package br.com.marealta.pricing;
313	
314	import java.time.LocalDate;
315	import java.time.Month;
316	
317	public class SeasonCalculator {
318	    public static boolean isHighSeason(LocalDate date) {
319	        Month month = date.getMonth();
320	        int day = date.getDayOfMonth();
321	
322	        if (month == Month.JULY) {
323	            return true;
324	        }
325	
326	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
327	            return true;
328	        }
329	
330	        if (month == Month.DECEMBER && day >= 15) {
331	            return true;
332	        }
333	
334	        return false;
335	    }
336	}

