249	        YearMonth yearMonth = YearMonth.parse(period, DateTimeFormatter.ofPattern("yyyy-MM"));
250	
251	        List<ReservationStatus> statuses = List.of(
252	            ReservationStatus.CONFIRMED,
253	            ReservationStatus.CHECKED_IN,
254	            ReservationStatus.CHECKED_OUT,
255	            ReservationStatus.CANCELLED
256	        );
257	
258	        List<Reservation> reservations = reservationRepository.findByMonthAndStatuses(
259	            yearMonth.getYear(), yearMonth.getMonthValue(), statuses
260	        );
261	
262	        List<String> rows = new ArrayList<>();
263	        for (Reservation reservation : reservations) {
264	            BigDecimal netAmount = calculateNetAmount(reservation);
265	            rows.add(String.format("%d,%s,%s,%s,%s,%s",
266	                reservation.getId(),
267	                reservation.getRoomNumber(),
268	                reservation.getCheckIn().format(DATE_FORMATTER),
