278	    @Override
279	    protected String buildTotal(String period) {
280	        YearMonth yearMonth = YearMonth.parse(period, DateTimeFormatter.ofPattern("yyyy-MM"));
281	
282	        List<ReservationStatus> statuses = List.of(
283	            ReservationStatus.CONFIRMED,
284	            ReservationStatus.CHECKED_IN,
285	            ReservationStatus.CHECKED_OUT,
286	            ReservationStatus.CANCELLED
287	        );
288	
289	        List<Reservation> reservations = reservationRepository.findByMonthAndStatuses(
290	            yearMonth.getYear(), yearMonth.getMonthValue(), statuses
291	        );
292	
293	        BigDecimal total = reservations.stream()
294	            .map(this::calculateNetAmount)
