418	        reservation.setSubtotal(rs.getBigDecimal("subtotal"));
419	        reservation.setDiscount(rs.getBigDecimal("discount"));
420	        reservation.setTotal(rs.getBigDecimal("total"));
421	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
422	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
423	
424	        var refund = rs.getBigDecimal("refund");
425	        if (refund != null) {
426	            reservation.setRefund(refund);
427	        }
428	
429	        return reservation;
430	    }
